'use strict';

// Everything in this demo stays in this browser. No APIs or location requests.
const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const escapeHTML = value => String(value).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const icons = {
  home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',
  trips:'M5 7h14a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V9a2 2 0 0 1 2-2Zm3 0V4h8v3M8 7v14M16 7v14',
  compass:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM16 8l-3 5-5 3 3-5Z',
  spark:'m12 3 2.3 6.7L21 12l-6.7 2.3L12 21l-2.3-6.7L3 12l6.7-2.3ZM20 2v4M18 4h4',
  shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6ZM8 12l3 3 5-6',
  user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 21v-2a8 8 0 0 1 16 0v2',
  users:'M14 8a3 3 0 1 1-6 0 3 3 0 0 1 6 0ZM3 21v-3a6 6 0 0 1 12 0v3M17 5a3 3 0 0 1 0 6M18 15a4 4 0 0 1 3 4v2',
  pin:'M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 0 1 14 0ZM14 10a2 2 0 1 1-4 0 2 2 0 0 1 4 0Z',
  calendar:'M5 5h14a2 2 0 0 1 2 2v13H3V7a2 2 0 0 1 2-2ZM3 10h18M7 3v4M17 3v4M7 14h2M13 14h2M7 17h2',
  clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM12 7v5l3 2',
  arrow:'M4 12h16M14 6l6 6-6 6',
  plus:'M12 5v14M5 12h14',
  moon:'M20 14a9 9 0 0 1-10-10 9 9 0 1 0 10 10Z',
  sun:'M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM12 2v2M12 20v2M2 12h2M20 12h2M5 5l1 1M18 18l1 1M5 19l1-1M18 6l1-1',
  bell:'M5 17h14l-2-3V9a5 5 0 0 0-10 0v5ZM10 21h4M12 2v2',
  bookmark:'M6 3h12v18l-6-4-6 4Z',
  map:'m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2ZM9 3v16M15 5v16',
  car:'m5 8 2-5h10l2 5M3 9h18v9H3ZM6 18v3M18 18v3M6 13h2M16 13h2',
  check:'m5 12 4 4L19 6',
  phone:'M7 3H3c0 10 8 18 18 18v-4l-5-2-2 2a14 14 0 0 1-7-7l2-2Z',
  hospital:'M5 21V4h14v17ZM9 21v-5h6v5M12 7v6M9 10h6',
  share:'M18 5 6 12l12 7M8 12a2 2 0 1 1-4 0 2 2 0 0 1 4 0ZM20 5a2 2 0 1 1-4 0 2 2 0 0 1 4 0ZM20 19a2 2 0 1 1-4 0 2 2 0 0 1 4 0Z',
  download:'M12 3v12M7 10l5 5 5-5M4 16v5h16v-5',
  food:'M4 3v6a3 3 0 0 0 6 0V3M7 3v18M19 3c-5 2-5 10 0 10ZM19 13v8',
  hotel:'M3 21V7h18v14M3 17h18M7 11h3v3H7ZM14 11h3v3h-3Z',
  send:'m3 3 18 9-18 9 3-9ZM6 12h15',
  leaf:'M20 3C8 1 2 8 6 15s15 4 14-12ZM4 21 16 8',
  route:'M5 6h10a4 4 0 0 1 0 8H9a4 4 0 0 0 0 8h10M7 5a2 2 0 1 1-4 0 2 2 0 0 1 4 0Z'
};
function icon(name) { return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name] || icons.compass}"/></svg>`; }
function hydrateIcons() { $$('[data-icon]').forEach(el => { el.innerHTML = icon(el.dataset.icon); }); }
const navItems = [['dashboard','home','Dashboard'],['trips','trips','Trips'],['explore','compass','Explore'],['ai','spark','AI Planner'],['safety','shield','Safety'],['profile','user','Profile']];
const places = [
  {id:1,name:'Matale Aluvihare Temple',category:'Heritage',duration:40,drive:80,detour:'1.2 km',extra:'5 min',best:'Early morning',reason:'A peaceful first stop, with rock temples and stories tucked into the hillside.',scene:'temple',x:32,y:68},
  {id:2,name:'Dambulla Cave Temple',category:'Culture',duration:90,drive:65,detour:'2.4 km',extra:'10 min',best:'Before 10 AM',reason:'Ancient cave art and a sweeping view make this your main cultural stop.',scene:'temple',x:40,y:53},
  {id:3,name:'Sigiriya Viewpoint',category:'Nature',duration:40,drive:35,detour:'9.5 km',extra:'30 min',best:'Late morning',reason:'All the drama of Lion Rock, with a viewpoint visit instead of a long climb.',scene:'sigiriya',x:49,y:43},
  {id:4,name:'Habarana Food Stop',category:'Food',duration:60,drive:25,detour:'0.5 km',extra:'3 min',best:'12–1 PM',reason:'Slow down over a Sri Lankan rice-and-curry lunch before the coastal leg.',scene:'forest',x:52,y:34},
  {id:5,name:'Kantale Tank Viewpoint',category:'Viewpoint',duration:25,drive:100,detour:'1.0 km',extra:'5 min',best:'Afternoon',reason:'Stretch your legs beside open water and a wonderfully quiet horizon.',scene:'lake',x:65,y:26},
  {id:6,name:'Trincomalee Beach Sunset',category:'Beach',duration:60,drive:55,detour:'3.0 km',extra:'10 min',best:'Late afternoon',reason:'End the road day by the ocean. Enjoy the evening light on the east coast.',scene:'beach',x:80,y:16}
];
const demoTrip = {name:'Kandy to Trincomalee Weekend',start:'Kandy',destination:'Trincomalee',transport:'Car',date:'2026-10-17',time:'06:00',group:5,budget:'Medium',style:'Balanced',interests:['Beaches','Temples','Food','Nature','Viewpoints']};
let state = {screen:'dashboard',trip:{...demoTrip},selected:[1,2,3,4,5,6],theme:'light',notifications:true,profile:{name:'Amaya Kumar',email:'amaya.kumar@example.com',city:'Colombo',language:'English'}};
try { const saved = JSON.parse(localStorage.getItem('trippulse-v1') || 'null'); if(saved && saved.trip && Array.isArray(saved.selected)) state = {...state,...saved,screen:'dashboard',selected:saved.selected.filter(id=>places.some(p=>p.id===id))}; } catch { /* Storage is optional, including when opened as a local file. */ }
let draft = {...state.trip,interests:[...state.trip.interests]};
let formStep = 1;
let mapStop = 2;
let layers = new Set(['Places']);
let toastTimer;
let chat = [{role:'user',text:'Is this trip too packed?'},{role:'assistant',text:'Your plan looks balanced if you start around 6:00 AM. Dambulla and Habarana are realistic stops, but adding a Sigiriya Rock climb may make the day too long. I recommend keeping it as a viewpoint stop only.'}];
function persist() { try {localStorage.setItem('trippulse-v1',JSON.stringify(state));} catch { /* Continue in memory. */ } }
function toast(message) { $('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000); }
function button(label, nav, type='secondary', symbol='') { return `<button class="btn ${type}" data-nav="${nav}">${symbol?icon(symbol):''}${label}</button>`; }
function avatars(label='Your travel crew') { return `<div class="avatar-stack" aria-label="${label}"><span class="avatar">AK</span><span class="avatar">NP</span><span class="avatar">DS</span><span class="avatar">+2</span><small>${label}</small></div>`; }
function dateText(date=state.trip.date, short=false) { return new Date(`${date}T12:00:00`).toLocaleDateString('en-GB',{day:'numeric',month:short?'short':'long',...(!short&&{year:'numeric'})}); }
function heading(title,subtitle,action='') { return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`; }
function sectionHeading(title,link='',nav='') { return `<div class="section-heading"><h2>${title}</h2>${link?`<button class="text-button" data-nav="${nav}">${link} <span>↗</span></button>`:''}</div>`; }
function isDemoRoute() { return state.trip.start.trim().toLowerCase()==='kandy' && state.trip.destination.trim().toLowerCase()==='trincomalee'; }
function routeNotice() { return isDemoRoute()?'':`<div class="inline-notice">${icon('map')}<div><strong>Sample route preview</strong><p>Your trip details are saved. Places, travel estimates, and the illustrated map still use the Kandy → Trincomalee demo route.</p></div></div>`; }

// Original SVG scenery keeps the entire prototype self-contained and available offline.
function scene(kind='sigiriya', id='scene') {
  const beach = kind==='beach', lake=kind==='lake', temple=kind==='temple', forest=kind==='forest';
  return `<svg class="landscape" viewBox="0 0 800 390" preserveAspectRatio="xMidYMid slice" role="img" aria-label="Illustration of ${beach?'the Sri Lankan coast':lake?'a peaceful reservoir':temple?'a temple in the hills':forest?'a lush tropical forest':'Sigiriya and the Sri Lankan highlands'}"><defs><linearGradient id="sky-${id}" x2="0" y2="1"><stop stop-color="${beach?'#d7dfcb':'#abc7b5'}"/><stop offset="1" stop-color="#f0e4b8"/></linearGradient><linearGradient id="land-${id}" x2="0" y2="1"><stop stop-color="#547965"/><stop offset="1" stop-color="#163e36"/></linearGradient><linearGradient id="rock-${id}" x2=".8" y2="1"><stop stop-color="#c0a775"/><stop offset=".45" stop-color="#8a8061"/><stop offset="1" stop-color="#536b51"/></linearGradient><filter id="grain-${id}"><feTurbulence type="fractalNoise" baseFrequency=".55" numOctaves="3" stitchTiles="stitch"/><feColorMatrix type="saturate" values="0"/><feComponentTransfer><feFuncA type="linear" slope=".08"/></feComponentTransfer><feBlend in="SourceGraphic" mode="multiply"/></filter></defs><g filter="url(#grain-${id})"><path fill="url(#sky-${id})" d="M0 0h800v390H0z"/><circle cx="650" cy="83" r="40" fill="#f7e6aa" opacity=".85"/><path d="M0 210 105 127 162 165 273 95 397 196 490 132 630 189 728 116 800 162V390H0Z" fill="#91ad91" opacity=".5"/><path d="M0 237 158 184 290 224 430 158 554 201 689 149 800 207V390H0Z" fill="#739575" opacity=".7"/>
  ${beach||lake?`<path d="M0 232Q200 208 400 229T800 217V390H0Z" fill="${beach?'#5ba9a0':'#83b3a0'}"/><path d="M0 266Q200 244 480 263T800 250M20 310Q200 287 420 309T800 291" fill="none" stroke="#d0e4c5" stroke-width="3" opacity=".5"/><path d="M0 320Q220 279 422 338T800 345V390H0Z" fill="#e8d8a8"/>`:''}
  ${!beach&&!lake?`<path d="M0 265Q160 206 320 248T800 223V390H0Z" fill="#486f51"/>`:''}
  ${!beach&&!lake&&!temple&&!forest?`<path d="m332 242 12-53 16-9 6-47 20-17 6-40 19-14 93-4 20 17 5 33 14 9 12 64 18 16 4 47Z" fill="url(#rock-${id})"/><path d="m392 76 25-8 83-6 18 15-48 7-59-2Z" fill="#506746"/><path d="m378 122 13 89m16-119-6 132m26-135-6 143m39-142 9 151m27-144 7 151m21-98 9 91" stroke="#d3b88a" stroke-width="3" opacity=".35"/><path d="m335 242 68-22 86 4 94 21-42 19-143 7Z" fill="#355e43"/>`:''}
  ${temple?`<path d="M371 237v-43h143v43Z" fill="#f6eed3"/><path d="M355 195q86-14 88-76 0 58 85 76Z" fill="#ece6cc"/><path d="M438 123v-29h8v29M439 90h7v-14h-7Z" fill="#cead66"/><path d="M350 239h183v9H350Z" fill="#e1d2ad"/><path d="M305 267h279v12H305Z" fill="#ccc5a6"/><path d="m310 254 30-10h191l34 10Z" fill="#efe4c5"/><path d="M437 213h15v25h-15Z" fill="#a39879"/>`:''}
  <path d="M0 328Q95 256 185 309T373 303Q504 277 608 310T800 275V390H0Z" fill="url(#land-${id})"/>
  ${beach?`<path d="M0 364Q170 304 340 351T800 370V390H0Z" fill="#dfd0a5"/>`:''}
  <g fill="#234d3d"><path d="M87 390 106 193h7L97 390Z"/><path d="M109 209q-44-70-90-23 57-15 87 25-73-42-96 18 52-39 97-13-6-75 47-88-34 45-41 85 52-73 97-31-57-11-97 33 64-14 81 30-50-24-82-23Z"/><path d="M714 390 697 224h-6l12 166Z"/><path d="M695 237q-44-64-76-21 48-10 73 22-55-23-77 20 38-28 78-16-4-65 40-78-28 35-35 74 41-48 74-22-43-5-73 27 53-8 61 29-38-24-63-25Z"/></g><g fill="#143c31"><path d="M0 390v-29l15-17 12 11 17-27 24 28 15-10 22 32 23-17 29 29ZM580 390l29-21 21 10 30-28 19 9 27-24 18 19 20-14 19 13 14-7 23 20v23Z"/></g><path d="m565 73 8-4 8 4m14-15 7-3 7 3" fill="none" stroke="#416854" stroke-width="2" opacity=".6"/></g></svg>`;
}

function renderNav() {
  const active = ['overview','create','itinerary','map'].includes(state.screen)?'trips':state.screen==='welcome'?'dashboard':state.screen;
  $('.desktop-nav').innerHTML=navItems.map(([key,symbol,label])=>`<button class="nav-item ${active===key?'active':''}" data-nav="${key}" ${active===key?'aria-current="page"':''}>${icon(symbol)}${label}${key==='ai'?'<span class="nav-new">AI</span>':''}</button>`).join('');
  $('.bottom-nav').innerHTML=navItems.filter(([key])=>key!=='ai').map(([key,symbol,label])=>`<button class="bottom-item ${active===key?'active':''}" data-nav="${key}" ${active===key?'aria-current="page"':''}>${icon(symbol)}<span>${key==='dashboard'?'Home':label}</span></button>`).join('');
  const labels={overview:'Trip workspace',create:'Create a trip',itinerary:'Your itinerary',map:'Route map',welcome:'Welcome to TripPulse'};
  $('#page-label').textContent=labels[state.screen]||navItems.find(([key])=>key===state.screen)?.[2]||'Dashboard';
}
function navigate(screen) {
  if(!screens[screen])screen='dashboard';
  if(screen==='create' && state.screen!=='create'){draft={...state.trip,interests:[...state.trip.interests]};formStep=1;}
  state.screen=screen;
  if(location.hash!==`#${screen}`)history.pushState(null,'',`#${screen}`);
  render();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});
}
function render() {
  renderNav();$('#main').innerHTML=`<div class="screen-enter">${screens[state.screen]()}</div>`;hydrateIcons();updateTheme();
}
function updateTheme() {
  document.body.classList.toggle('dark',state.theme==='dark');
  $$('.theme-button').forEach(el=>{el.innerHTML=icon(state.theme==='dark'?'sun':'moon');el.setAttribute('aria-label',`Switch to ${state.theme==='dark'?'light':'dark'} mode`);});
  const toggle=$('[data-action="theme"][role="switch"]');if(toggle)toggle.setAttribute('aria-checked',String(state.theme==='dark'));
}
function tripCard() {
  return `<article class="card"><div class="trip-card-visual">${scene('beach','upcoming')}<span class="pill">● &nbsp; UPCOMING ADVENTURE</span><span class="trip-tag">A LITTLE CULTURE. A LOT OF COAST.</span></div><div class="trip-card-body"><div class="trip-card-title"><h3>${escapeHTML(state.trip.name)}</h3><span class="pill orange">Planning</span></div><div class="trip-meta"><span>${icon('calendar')}${dateText(undefined,true)}</span><span>${icon('users')}${state.trip.group} travelers</span><span>${icon('car')}${escapeHTML(state.trip.transport)} trip</span></div><div class="trip-card-bottom">${avatars()}${button('View trip','overview','subtle','arrow')}</div></div></article>`;
}
function discoverCards() {
  return [{name:'A different kind of rush.',sub:'Sigiriya · Culture meets adventure',type:'sigiriya',tag:'INTO THE WILD',id:3},{name:'Take the scenic route.',sub:'Hill country · Slow down a little',type:'forest',tag:'OFF THE BEATEN PATH',id:1},{name:'Chase the salty air.',sub:'Trincomalee · Your coastal escape',type:'beach',tag:'COASTAL CALLING',id:6}].map((p,i)=>`<button class="discover-card" data-place="${p.id}"><div class="discover-image">${scene(p.type,`discover-${i}`)}<span class="pill">${p.tag}</span></div><div class="discover-info"><h3>${p.name}</h3><p>${icon('pin')}${p.sub}</p><span>↗</span></div></button>`).join('');
}
function dashboard() {
  return `${heading(`Good morning, traveler <span class="greeting-wave">☀</span>`,"A new day. A new direction. Where will your curiosity take you?",`<span class="date-label">${icon('calendar')}Saturday, 3 October 2026</span>`)}
  <section class="hero"><div class="hero-art">${scene('sigiriya','hero')}</div><div class="hero-copy"><div class="hero-kicker">${icon('spark')} LESS PLANNING. MORE LIVING.</div><h2>Your next great escape,<br><em>beautifully planned.</em></h2><p>Hidden gems, good company, and the open road.<br>Let’s find your pulse of Sri Lanka.</p>${button('Create New Trip','create','light','plus')}${button('Explore the possibilities','welcome','ghost')}</div><div class="hero-floating"><span>✧</span><div><strong>A better way to wander</strong><small>A little AI. A lot of adventure.</small></div></div><div class="hero-location">${icon('pin')}Sigiriya, Sri Lanka</div></section>
  <section class="stats" aria-label="Your travel stats">${[['trips','01','Trips planned','Ready to go'],['bookmark',String(state.selected.length).padStart(2,'0'),'Places saved','On your route'],['users','04','Friends invited','Your people'],['shield','09','Safety tools ready','Demo tools']].map(([symbol,value,label,note])=>`<div class="card stat"><span class="stat-icon">${icon(symbol)}</span><div><strong>${value}</strong><small>${label}</small></div><span class="stat-note">${note}</span></div>`).join('')}</section>
  <div class="dashboard-grid"><section>${sectionHeading('Your next adventure','All trips','trips')}${tripCard()}<div class="card continue-card"><span class="stat-icon">${icon('route')}</span><div><strong>A good plan is coming together</strong><p>${state.selected.length} stops saved. Make this trip your own.</p></div><button class="text-button" data-nav="explore">Continue planning →</button></div></section><section>${sectionHeading('A little help along the way')}<div class="quick-actions">${[['spark','Generate itinerary','Your day, thoughtfully mapped','itinerary'],['users','Invite your people','Good trips need good company','invite'],['shield','Safety Center','Peace of mind, wherever you go','safety'],['compass','Ask TripPulse AI','A local perspective, on demand','ai']].map(([symbol,label,sub,action])=>`<button class="quick-action" ${action==='invite'?'data-action="invite"':`data-nav="${action}"`}>${icon(symbol)}<strong>${label}</strong><small>${sub}</small></button>`).join('')}</div><div class="ai-note"><div class="eyebrow">${icon('spark')} YOUR AI COMPANION</div><h3>The best detours become the best stories.</h3><p>Your Kandy–Trincomalee route passes ancient temples, quiet lakes, and a few very good lunch spots.</p><button class="text-button" data-nav="explore">Find your along-the-way moments →</button></div></section></div>
  <section class="discover-section">${sectionHeading('A little inspiration, a lot of possibility','Explore Sri Lanka','explore')}<div class="discover-grid">${discoverCards()}</div></section>`;
}
function welcome() {
  return `${heading('Go somewhere that stays with you.','Plan smarter. Travel safer. Feel the pulse of Sri Lanka.')}
  <section class="hero welcome-hero"><div class="hero-art">${scene('sigiriya','welcome')}</div><div class="hero-copy"><div class="hero-kicker">${icon('pin')} ONE ISLAND. ENDLESS POSSIBILITIES.</div><h2>Find your people.<br>Find your way.<br><em>Feel the pulse.</em></h2><p>Create route-based Sri Lanka trips, discover places along the way, coordinate your group, and access safety support when it matters.</p><div class="button-row">${button('Start Planning','create','light','plus')}${button('View Demo Trip','overview','ghost','arrow')}</div></div><div class="hero-floating"><span>✧</span><div><strong>Your AI travel companion</strong><small>“A sunset stop? I know just the place.”</small></div></div><div class="hero-location">${icon('pin')}Kandy ──●── Dambulla ──●── Trincomalee</div></section>
  <div class="welcome-features">${[['route','The journey is the destination.','Discover thoughtful stops in travel order, with time to actually enjoy them.'],['users','Better together.','Build a shared plan for your favorite people, from first idea to final sunset.'],['shield','Adventure with peace of mind.','Keep emergency information and support tools close throughout your trip.']].map(([symbol,title,copy])=>`<div class="card card-pad"><span class="stat-icon">${icon(symbol)}</span><h3>${title}</h3><p>${copy}</p></div>`).join('')}</div>`;
}
function trips() {return `${heading('Your adventures, all in one place.','The next good story starts here.',button('Create New Trip','create','','plus'))}<div class="content-grid"><div>${tripCard()}</div><div class="card card-pad"><span class="stat-icon">${icon('bookmark')}</span><h2 style="margin-top:17px">Keep the good ideas close.</h2><p class="muted" style="margin:10px 0 20px">${state.selected.length} stops are waiting in your route collection. Add your favorites and shape a day that feels like you.</p>${button('Continue planning','explore','subtle','arrow')}</div></div>`;}
function routeStrip() {return `<div class="route-strip"><div class="route-end"><small>Starting from</small><strong>${escapeHTML(state.trip.start)}</strong></div><div class="route-connector"><span>${isDemoRoute()?'~240 km · sample route':'Custom route'}</span></div><div class="route-end"><small>Heading to</small><strong>${escapeHTML(state.trip.destination)}</strong></div></div>`;}
function overview() {
  return `${heading(escapeHTML(state.trip.name),'Your people. Your places. Your kind of adventure.',button('Safety Center','safety','secondary','shield'))}${routeNotice()}
  <div class="content-grid"><div class="stack"><section class="card card-pad"><div class="section-heading"><h2>Let’s take the scenic route.</h2><span class="pill orange">● Planning</span></div>${routeStrip()}<div class="detail-grid">${[['Departure',`${dateText()} · ${state.trip.time}`],['Travel crew',`${state.trip.group} travelers`],['Transport',state.trip.transport],['Budget',state.trip.budget],['Travel style',state.trip.style],['Interests',state.trip.interests.join(', ')||'Open to discovery']].map(([label,value])=>`<div><small>${label}</small><strong>${escapeHTML(value)}</strong></div>`).join('')}</div><div class="workspace-tabs">${button('Generate Suggestions','explore','','spark')}${button('View Itinerary','itinerary','secondary','calendar')}${button('Open Map','map','secondary','map')}${button('Ask AI','ai','secondary','spark')}</div><button class="text-button" data-nav="create">Edit trip details →</button></section><section class="card card-pad">${sectionHeading('Your along-the-way moments','See all places','explore')}${places.filter(p=>state.selected.includes(p.id)).slice(0,3).map(p=>`<div class="list-row"><span class="number">${p.id}</span><div><strong>${p.name}</strong><p>${p.category} · ${p.duration} min visit · ${p.extra} detour</p></div><span class="pill">Saved</span></div>`).join('')||'<p class="muted">Your route is a blank canvas. Explore places to add your first stop.</p>'}</section><section class="card card-pad">${sectionHeading('A glimpse of your day','Full itinerary','itinerary')}${timelineMarkup(buildSchedule().slice(0,3))}</section></div><div class="stack">${mapMarkup(false)}<section class="card card-pad">${sectionHeading('Your travel crew')}<p class="muted" style="font-size:11px;margin-bottom:15px">Sample group · ${state.trip.group} travelers planned</p>${avatars('5 demo members')}<div class="list-row"><span class="avatar">AK</span><div><strong>${escapeHTML(state.profile.name)}</strong><p>Trip organizer · You</p></div><span class="pill">Owner</span></div><button class="btn secondary wide" data-action="invite">${icon('users')}Invite friends</button></section><section class="card card-pad"><span class="stat-icon">${icon('shield')}</span><h3 style="margin-top:12px">A little preparation goes a long way.</h3><ul class="check-list"><li>Emergency information available</li><li>2 sample trusted contacts</li><li>Offline plan ready to download</li></ul><p class="simulation-note">Demo readiness only. No live monitoring or alerts.</p>${button('Review safety tools','safety','subtle','arrow')}</section></div></div>`;
}
function field(label,name,value,type='text',extra='') {return `<label class="field ${extra}">${label}<input name="${name}" type="${type}" value="${escapeHTML(value)}" required ${type==='text'?'maxlength="100"':''} ${name==='group'?'min="1" max="30"':''}></label>`;}
function createTrip() {
  let fields;
  if(formStep===1) fields=`<div class="form-grid">${field('Give your adventure a name','name',draft.name,'text','full')}${field('Start location','start',draft.start)}${field('Destination','destination',draft.destination)}<label class="field full">How are you getting there?<select name="transport">${['Car','Van','Bus','Train','Motorbike'].map(v=>`<option ${draft.transport===v?'selected':''}>${v}</option>`).join('')}</select></label></div>`;
  else if(formStep===2) fields=`<div class="form-grid">${field('Departure date','date',draft.date,'date')}${field('Start time','time',draft.time,'time')}${field('Number of travelers','group',draft.group,'number')}<label class="field">Budget level<select name="budget">${['Low','Medium','Premium'].map(v=>`<option ${draft.budget===v?'selected':''}>${v}</option>`).join('')}</select></label></div>`;
  else fields=`<p class="muted" style="font-size:12px;margin-top:20px">What makes you want to pull over?</p><div class="interest-chips">${['Beaches','Temples','Heritage','Nature','Wildlife','Waterfalls','Hiking','Food','Viewpoints','Adventure','Family Friendly','Budget Friendly'].map(interest=>`<button type="button" class="chip ${draft.interests.includes(interest)?'selected':''}" data-interest="${interest}" aria-pressed="${draft.interests.includes(interest)}">${draft.interests.includes(interest)?'✓ ': '+ '}${interest}</button>`).join('')}</div><h3>Your kind of pace</h3><div class="style-options" style="margin-top:13px">${[['Relaxed','☁','More breathing room. Fewer stops.'],['Balanced','☀','The highlights, without the hurry.'],['Packed','⚡','A full day of discoveries.']].map(([style,symbol,copy])=>`<button type="button" class="style-option ${draft.style===style?'selected':''}" data-style="${style}" aria-pressed="${draft.style===style}">${symbol}<strong>${style}</strong><small>${copy}</small></button>`).join('')}</div>`;
  return `${heading('Every great trip starts with an idea.','A few details now. A world of possibilities next.')}<div class="form-layout"><div class="stepper">${['Route','Details','Preferences'].map((label,i)=>`${i?'<i></i>':''}<div class="step ${formStep===i+1?'active':formStep>i+1?'done':''}" ${formStep===i+1?'aria-current="step"':''}><span>${formStep>i+1?'✓':i+1}</span>${label}</div>`).join('')}</div><div class="content-grid"><form id="trip-form" class="card card-pad"><span class="eyebrow muted">STEP ${formStep} OF 3</span><h2 style="margin-top:7px">${['Where are we headed?','Make room for the adventure.','Make this trip feel like you.'][formStep-1]}</h2>${fields}<div class="form-actions"><button class="btn secondary" type="button" data-action="form-back">${formStep===1?'Cancel':'← Back'}</button><button class="btn" type="submit">${formStep===3?'Generate Trip Workspace':'Continue'} ${icon('arrow')}</button></div></form><aside class="card card-pad form-aside"><span class="stat-icon">${icon('spark')}</span><h2 style="margin-top:16px">Made around you.</h2><p>A good trip is more than a list of places. It’s the right stops, the right pace, and the people you bring along.</p><ul class="check-list"><li>Discover along your route</li><li>Leave room for the unexpected</li><li>Keep safety within reach</li></ul>${scene('sigiriya','form')}<p class="simulation-note">Prototype tip: use Kandy → Trincomalee to explore the complete sample route.</p></aside></div></div>`;
}
function explore() {
  return `${heading('Good things happen along the way.','Handpicked stops, in travel order. Save the ones that speak to you.',button('View route','map','secondary','map'))}${routeNotice()}<div class="inline-notice">${icon('spark')}<div><strong>A little culture, a little nature, a little ocean.</strong><p>Kandy → Trincomalee · 6 sample recommendations · Estimates are illustrative, not live routing.</p></div></div><div class="places-grid">${places.map(p=>`<article class="card place-card"><div class="discover-image">${scene(p.scene,`place-${p.id}`)}<span class="pill">${p.category.toUpperCase()}</span><span class="place-order" aria-label="Stop ${p.id}">${p.id}</span></div><div class="place-body"><h3>${p.name}</h3><p>${p.reason}</p><div class="place-facts"><span>${icon('clock')}${p.duration} min visit</span><span>${icon('route')}${p.detour} off route</span><span>${icon('car')}+${p.extra} travel</span><span>${icon('sun')}${p.best}</span></div><button class="btn ${state.selected.includes(p.id)?'subtle':'secondary'} wide" data-toggle-place="${p.id}" aria-pressed="${state.selected.includes(p.id)}">${icon(state.selected.includes(p.id)?'check':'plus')}${state.selected.includes(p.id)?'Added to trip · Remove':'Add to trip'}</button></div></article>`).join('')}</div><div class="selection-bar"><div><strong id="selected-count">${state.selected.length} places selected</strong><small>A journey that’s yours to shape.</small></div><button class="btn" data-action="generate">${icon('spark')}Generate Itinerary</button></div>`;
}

function formatTime(minutes) {const day=Math.floor(minutes/1440);const h=Math.floor(minutes/60)%24;return `${h%12||12}:${String(minutes%60).padStart(2,'0')} ${h>=12?'PM':'AM'}${day?' +'+day+'d':''}`;}
function buildSchedule() {
  const [h,m]=state.trip.time.split(':').map(Number);let clock=h*60+m;
  const schedule=[{time:clock,title:`Start from ${state.trip.start}`,category:'Departure',duration:0,travel:0}];
  let pendingDrive=0;
  places.forEach(p=>{pendingDrive+=p.drive;if(state.selected.includes(p.id)){clock+=pendingDrive;schedule.push({time:clock,title:p.name,category:p.category,duration:p.duration,travel:pendingDrive});clock+=p.duration;pendingDrive=0;}});
  clock+=pendingDrive+15;schedule.push({time:clock,title:`${state.trip.destination} · Check-in / Rest`,category:'Rest',duration:0,travel:pendingDrive+15});return schedule;
}
function timelineMarkup(schedule) {return `<div class="timeline">${schedule.map(item=>`<div class="timeline-item"><span class="timeline-time">${formatTime(item.time)}</span><div class="timeline-point"><span></span></div><div class="timeline-info"><span class="pill ${item.category==='Food'?'orange':''}">${item.category}</span><h3>${escapeHTML(item.title)}</h3><p>${item.travel?`${item.travel} min travel from previous stop`:'Your road day begins here'}${item.duration?` · ${item.duration} min visit`:''}</p></div></div>`).join('')}</div>`;}
function planAssessment() {const s=buildSchedule(),duration=s.at(-1).time-s[0].time,late=s.at(-1).time>20*60;return late?{title:'An earlier start would give you more breathing room.',text:'Your current plan ends after 8 PM. Remove a major stop or leave earlier. Evening light is not guaranteed.'}:duration>780?{title:'This is a full road day. Leave a little breathing room.',text:'Consider removing a major attraction for a more relaxed pace. Travel estimates include no live traffic.'}:{title:'This plan is balanced, with a full day on the road.',text:'You have time for your key stops without adding a rock climb. Take breaks, and keep a buffer for traffic.'};}
function itinerary() {
  const assessment=planAssessment();
  return `${heading('A day worth looking forward to.',`${dateText()} · ${escapeHTML(state.trip.start)} → ${escapeHTML(state.trip.destination)} · ${state.selected.length} selected stops`,button('Edit stops','explore','secondary','plus'))}${routeNotice()}<div class="inline-notice">${icon('spark')}<div><strong>${assessment.title}</strong><p>${assessment.text}</p></div></div><div class="content-grid"><section class="card card-pad"><div class="section-heading"><h2>Your road day</h2><span class="pill">${escapeHTML(state.trip.style)} pace</span></div>${timelineMarkup(buildSchedule())}<div class="form-actions"><button class="btn secondary" data-action="recalculate">${icon('route')}Recalculate</button><button class="btn" data-action="save-offline">${icon('download')}Save Offline</button></div><p class="simulation-note">Sample driving estimates. Other transport modes still use this driving schedule. Check access, travel conditions, opening times, and bookings before departure.</p></section><aside class="stack">${mapMarkup(false)}<div class="card card-pad"><span class="stat-icon">${icon('spark')}</span><h3 style="margin-top:14px">Room for a little spontaneity.</h3><p class="muted" style="font-size:12px;margin:9px 0 18px">Keep Sigiriya to a viewpoint stop. Save the climb for a day when you can give it the time it deserves.</p>${button('Ask AI to improve','ai','subtle','spark')}${button('Open Map','map','secondary','map')}</div></aside></div>`;
}
function mapMarkup(large=false) {
  const p=places.find(p=>p.id===mapStop)||places[0];
  return `<div class="map ${large?'map-large':''}" aria-label="Illustrative Kandy to Trincomalee map, not for navigation"><svg class="map-canvas" viewBox="0 0 500 600" preserveAspectRatio="none" aria-hidden="true"><rect width="500" height="600" fill="#e7eee2"/><path d="M407-20Q398 81 440 155T445 324Q421 402 500 461V-20Z" fill="#b4d9d8"/><path d="M0 320Q83 261 164 300T305 241L285 166Q151 113 83 179T0 152Z" fill="#d1dfc7"/><path d="M39 456Q98 387 196 428T373 340L388 446 223 518Z" fill="#d4e2ca"/><path d="M40 0Q109 114 65 240T160 472L133 600M0 135Q128 132 256 182T460 131M0 432Q202 337 369 443T500 491M243 0Q202 165 257 300T337 600" fill="none" stroke="#f9faf0" stroke-width="14"/><path d="M40 0Q109 114 65 240T160 472L133 600M0 135Q128 132 256 182T460 131M0 432Q202 337 369 443T500 491M243 0Q202 165 257 300T337 600" fill="none" stroke="#d4d9c8" stroke-width="1"/><path d="M150 480Q152 435 160 408T200 318L245 258 260 204Q288 154 325 156L400 96" fill="none" stroke="#fff" stroke-width="9"/><path d="M150 480Q152 435 160 408T200 318L245 258 260 204Q288 154 325 156L400 96" fill="none" stroke="#1c9280" stroke-width="4" stroke-dasharray="7 5"/><path d="M288 164q20-34 40-8 12 27-15 25Z" fill="#a9cecd"/><text x="95" y="502" class="map-label">Kandy</text><text x="88" y="404" class="map-label small">Matale</text><text x="120" y="315" class="map-label small">Dambulla</text><text x="265" y="267" class="map-label small">Sigiriya</text><text x="190" y="204" class="map-label small">Habarana</text><text x="316" y="186" class="map-label small">Kantale</text><text x="329" y="66" class="map-label">Trincomalee</text><text x="436" y="288" class="map-label small" transform="rotate(90 436 288)">INDIAN OCEAN</text></svg><div class="map-caption"><strong>Kandy → Trincomalee</strong>~240 km · ${state.selected.length} saved stops · Illustrated map</div><span class="map-marker" style="left:30%;top:80%" aria-label="Start: Kandy">S</span>${layers.has('Places')?places.filter(p=>state.selected.includes(p.id)).map(p=>`<button class="map-marker ${p.id===6?'destination':''} ${mapStop===p.id?'selected':''}" style="left:${p.x}%;top:${p.y}%" data-map-stop="${p.id}" aria-label="Show ${p.name}" aria-pressed="${mapStop===p.id}">${p.id===6?'D':p.id}</button>`).join(''):''}${layers.has('Food')?'<span class="map-extra" style="top:39%;left:48%" title="Sample food stop">🍴</span>':''}${layers.has('Safety')?'<button class="map-extra" style="top:61%;left:36%" data-action="hospital" aria-label="Sample hospital information">✚</button><button class="map-extra" style="top:23%;left:72%" data-action="police-station" aria-label="Sample police station information">♜</button>':''}${layers.has('Hotels')?'<span class="map-extra" style="top:22%;left:83%" title="Sample hotel marker">H</span>':''}<div class="map-sheet"><span class="number">${p.id}</span><div><strong>${p.name}</strong><p>${p.duration} min visit · ${p.category}</p></div>${large?`<button class="btn subtle" data-toggle-place="${p.id}">${state.selected.includes(p.id)?'Remove':'Add stop'}</button>`:button('Open map','map','subtle','arrow')}</div></div>`;
}
function mapScreen() {return `${heading('Follow your curiosity.','Your journey at a glance. Tap a numbered pin to explore a stop.',button('View itinerary','itinerary','secondary','calendar'))}${routeNotice()}<div class="map-controls" aria-label="Map layers">${[['Places','pin'],['Food','food'],['Safety','shield'],['Hotels','hotel']].map(([label,symbol])=>`<button class="chip ${layers.has(label)?'selected':''}" data-layer="${label}" aria-pressed="${layers.has(label)}">${icon(symbol)}${label}</button>`).join('')}</div>${mapMarkup(true)}<div class="map-legend"><span><i></i>Sample driving route</span><span>S · Start</span><span>D · Destination</span><span>Illustration only · Not to scale</span></div>`;}

const prompts=['Is this plan realistic?','What should we skip?','Adjust for late start','Suggest cheaper options','Best time for beach?','Find safety help'];
function chatMarkup() {return chat.map(m=>`<div class="message ${m.role}">${m.role==='assistant'?'<small>✧ TRIPPULSE AI · SIMULATED</small>':''}${escapeHTML(m.text)}</div>`).join('');}
function aiScreen() {return `${heading('A little local wisdom, on demand.','Meet your thoughtful travel companion. Big ideas, practical advice.')}<div class="content-grid"><section class="card chat-card"><div class="chat-header"><span class="ai-avatar">✧</span><div><h2>TripPulse AI</h2><p>Demo assistant · ${escapeHTML(state.trip.start)} → ${escapeHTML(state.trip.destination)}</p></div></div><div class="chat-messages" id="chat-messages" role="log" aria-label="Conversation" aria-live="polite">${chatMarkup()}</div><form class="chat-input" id="chat-form"><label class="sr-only" for="chat-message" hidden>Message TripPulse AI</label><input id="chat-message" aria-label="Message TripPulse AI" maxlength="600" placeholder="A question, an idea, a change of plans…" required autocomplete="off"><button class="btn" type="submit" aria-label="Send message">${icon('send')}</button></form></section><aside class="stack"><div class="card card-pad"><h3>Let’s get you started.</h3><div class="prompt-list">${prompts.map(p=>`<button class="chip" data-prompt="${p}">${p} <span aria-hidden="true">↗</span></button>`).join('')}</div><p class="simulation-note">Scripted responses for this prototype. No AI service is connected, and no messages leave your browser.</p></div><div class="card card-pad"><span class="eyebrow" style="color:var(--teal)">✧ SMALL CHANGES. BETTER DAYS.</span><ul class="check-list"><li>Start early</li><li>Keep the beach for evening light</li><li>Avoid more than 2 major attractions</li></ul><button class="text-button" data-nav="itinerary">Take another look at your day →</button></div></aside></div>`;}
function getResponse(prompt) {
  const text=prompt.toLowerCase();
  if(/safe|help|emergency|hospital/.test(text))return 'Open the Safety Center for emergency action previews and offline information. This demo cannot call services, find your location, or send alerts. In a serious emergency, contact official emergency services immediately using your phone.';
  if(/late|start/.test(text))return 'For a later start, I would skip the Sigiriya viewpoint and keep Dambulla as your main cultural stop. Allow a proper lunch break at Habarana. Edit your departure time in trip details and the itinerary will update; this chat does not change your plan.';
  if(/cheap|budget|cost/.test(text))return 'For a lighter budget, prioritize the reservoir viewpoint, beach time, and a local rice-and-curry lunch. Choose one paid cultural attraction and share transport costs with your group. Check actual admission and transport prices before you go.';
  if(/beach|sunset/.test(text))return 'Keep Trincomalee beach for late afternoon, when the light softens. It is an east-coast beach, so the sun sets inland rather than over the sea. Treat this as relaxed beach time; check the actual weather and daylight before your trip.';
  if(/skip|remove/.test(text))return 'If you want more breathing room, skip the Sigiriya viewpoint detour and focus on Dambulla, a relaxed lunch, and the coast. If nature is your priority, you could keep Sigiriya and skip the temple instead. You can remove either stop in Explore.';
  if(/realistic|packed|balanced|plan/.test(text))return `With ${state.selected.length} selected stops and a ${state.trip.time} departure, this is ${buildSchedule().at(-1).time>1200?'a late-finishing':'a full'} road day. Keep Sigiriya to a viewpoint visit, give yourself a lunch break, and leave time for traffic. ${planAssessment().title} These are sample driving estimates, not a live route assessment.`;
  return `For your ${state.trip.start} to ${state.trip.destination} trip, I can demonstrate advice about timing, skipping stops, budget, beach time, and safety. Try one of the suggested questions. This prototype uses scripted answers, so I can’t research “${prompt.slice(0,100)}” or make bookings.`;
}
function sendMessage(text) {
  text=text.trim();if(!text)return;chat.push({role:'user',text});const response=getResponse(text);
  if(state.screen==='ai'){$('#chat-messages').innerHTML=chatMarkup();$('#chat-message').value='';$('#chat-messages').scrollTop=$('#chat-messages').scrollHeight;}
  setTimeout(()=>{chat.push({role:'assistant',text:response});if(state.screen==='ai'){$('#chat-messages').innerHTML=chatMarkup();$('#chat-messages').scrollTop=$('#chat-messages').scrollHeight;}},450);
}

const safetyActions=[['phone','Call Police','Preview an emergency call','call-police'],['hospital','Call Ambulance','Preview medical assistance','call-ambulance'],['hospital','Find Nearest Hospital','View sample nearby care','hospital'],['shield','Find Nearest Police Station','View a sample support point','police-station'],['share','Share My Location','Preview a location-sharing card','share-location'],['users','Alert Trip Members','Let your travel crew know','alert-members'],['user','Alert Trusted Contacts','Reach your people back home','alert-contacts'],['download','Offline Emergency Info','Download a local reference card','emergency-offline'],['shield','Emergency Profile','Keep useful details together','emergency-profile']];
function safety() {return `${heading('A little reassurance, wherever you go.','Your Safety Center. Clear actions, always within reach.')}<div class="safety-banner"><div><span class="eyebrow">WHEN EVERY MOMENT MATTERS</span><h2 style="margin-top:7px">Help starts with a clear next step.</h2><p>Keep calm, move to a safe place if you can, and contact official emergency services when you need urgent support.</p></div><button class="btn danger" data-action="emergency">${icon('phone')}Emergency Help</button></div><div class="inline-notice">${icon('shield')}<div><strong>Safety tools are in demo mode.</strong><p>No calls, alerts, location tracking, or real nearest-facility search. All people and locations below are samples.</p></div></div><div class="safety-grid">${safetyActions.map(([symbol,title,sub,action])=>`<button class="safety-action" data-action="${action}"><span class="stat-icon">${icon(symbol)}</span><strong>${title}</strong><small>${sub}</small></button>`).join('')}</div><div class="disclaimer">TripPulse helps you access support faster. In a serious emergency, contact official emergency services immediately.</div>`;}
function profile() {return `${heading('Make yourself at home.','Your preferences, your people, your peace of mind.')}<div class="content-grid"><div class="stack"><section class="card card-pad"><div class="profile-heading"><span class="avatar avatar-main">${escapeHTML(state.profile.name.split(' ').map(n=>n[0]).slice(0,2).join(''))}</span><div><h2>${escapeHTML(state.profile.name)}</h2><p>Curious by nature. Always up for a detour.</p></div></div><form id="profile-form"><div class="form-grid">${field('Name','name',state.profile.name)}${field('Email','email',state.profile.email,'email')}${field('Home city','city',state.profile.city)}<label class="field">Preferred language<select name="language">${['English','Sinhala','Tamil'].map(v=>`<option ${state.profile.language===v?'selected':''}>${v}</option>`).join('')}</select></label></div><p class="simulation-note" style="margin-bottom:14px">Preferences are saved on this device. Interface translations are not included in this prototype.</p><button class="btn" type="submit">Save profile</button></form></section><section class="card card-pad"><h2>The little preferences.</h2><div class="setting-row"><div><strong>Dark mode</strong><p>A softer view for after-hours planning.</p></div><button class="toggle" role="switch" aria-checked="${state.theme==='dark'}" aria-label="Dark mode" data-action="theme"></button></div><div class="setting-row"><div><strong>Trip notifications</strong><p>Demo preference · No push notifications are sent.</p></div><button class="toggle" role="switch" aria-checked="${state.notifications}" aria-label="Trip notifications" data-action="toggle-notifications"></button></div><div class="setting-row"><div><strong>About this prototype</strong><p>Local data. No account or connected services.</p></div><button class="text-button" data-nav="welcome">Explore →</button></div><button class="btn secondary" data-action="logout" style="margin-top:15px">Logout of demo</button></section></div><aside class="stack"><section class="card card-pad"><div class="section-heading"><h2>Emergency profile</h2><span class="pill">Sample complete</span></div><div class="list-row"><div><p>Emergency contact</p><strong>Nimal Kumar · Sample contact</strong></div></div><div class="detail-grid"><div><small>Blood group</small><strong>O+ (sample)</strong></div><div><small>Allergies</small><strong>None listed</strong></div></div><p class="simulation-note">Emergency profile information is optional and private by default. These are fictional demo details, not medical records.</p></section><section class="card card-pad"><h2>Your trusted people.</h2>${[['NK','Nimal Kumar','Family · Sample contact'],['SP','Sara Perera','Friend · Sample contact']].map(([initials,name,sub])=>`<div class="list-row"><span class="avatar">${initials}</span><div><strong>${name}</strong><p>${sub}</p></div><span class="pill">Trusted</span></div>`).join('')}<p class="simulation-note">Contact management is shown as a preview. No real contacts have been imported.</p></section></aside></div>`;}

const screens={dashboard,welcome,trips,overview,create:createTrip,explore,itinerary,map:mapScreen,ai:aiScreen,safety,profile};
function openModal(title,html) {$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();hydrateIcons();}
function closeModal() {$('#modal').close();}
function emergencyModal() {openModal('Emergency Help',`<p>Demo mode — these actions cannot contact emergency services.</p><div class="location-preview">${icon('pin')} Current location (mock)<strong> Near Dambulla, Central Province</strong><small>7.8742° N, 80.6511° E · Not your device location</small></div><div class="modal-options"><button class="btn secondary" data-action="call-police">${icon('phone')}Call Police · Preview</button><button class="btn secondary" data-action="call-ambulance">${icon('hospital')}Call Ambulance · Preview</button><button class="btn secondary" data-action="share-location">${icon('share')}Share Location · Preview</button><button class="btn danger" data-action="sos">${icon('shield')}Send SOS Alert · Confirm first</button></div>`);}
function confirmAlert(audience='trip members and trusted contacts') {openModal('Confirm SOS simulation',`<div class="sos-symbol">!</div><p>This would share a help request and your location with <strong>${escapeHTML(audience)}</strong>. In this prototype, nothing is sent.</p><div class="location-preview"><strong>Mock location: Near Dambulla</strong><small>“I need help. Please check in with me.”</small></div><div class="button-row"><button class="btn secondary" data-action="close-modal">Cancel</button><button class="btn danger" data-action="confirm-sos">Confirm demo SOS</button></div>`);}
function showPlace(id) {const p=places.find(p=>p.id===id);if(!p)return;openModal(p.name,`<div class="discover-image" style="height:180px;border-radius:10px;margin-bottom:18px">${scene(p.scene,'modal-place')}</div><span class="pill">${p.category}</span><p style="margin-top:12px">${p.reason}</p><div class="location-preview">${p.duration} min visit · ${p.detour} off the sample route<small>Best time: ${p.best} · Extra travel: ${p.extra}</small></div><button class="btn wide" data-action="explore-from-modal">Explore route recommendations ${icon('arrow')}</button>`);}
function downloadFile(name,content) {const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function offlinePlan() {downloadFile('TripPulse-itinerary.txt',`TRIPPULSE — OFFLINE TRIP PLAN\n${state.trip.name}\n${dateText()} | ${state.trip.start} → ${state.trip.destination}\n${state.trip.group} travelers | ${state.trip.transport} | ${state.trip.budget} budget\n\n${buildSchedule().map(p=>`${formatTime(p.time)} — ${p.title}\n   ${p.travel} min travel · ${p.duration} min visit`).join('\n\n')}\n\nSTATIC PROTOTYPE: Illustrative Kandy–Trincomalee driving estimates, not live routing. Verify travel conditions before leaving. No emergency alerts or calls are available in this file. In a serious emergency, contact official emergency services immediately.`);toast('Your offline itinerary download is ready.');}
function handleAction(action) {
  switch(action) {
    case 'theme':state.theme=state.theme==='light'?'dark':'light';persist();updateTheme();break;
    case 'notifications':openModal('Your travel notes',`<p>Sample notifications for your next adventure.</p><div class="list-row"><span class="stat-icon">${icon('bookmark')}</span><div><strong>${state.selected.length} route stops saved</strong><p>Your itinerary is ready to shape.</p></div></div><div class="list-row"><span class="stat-icon">${icon('shield')}</span><div><strong>A quick safety check before you go</strong><p>Review offline information with your group.</p></div></div><p class="simulation-note">${state.notifications?'Demo notifications enabled.':'Demo notifications are muted.'} No push service is connected.</p>`);break;
    case 'toggle-notifications':state.notifications=!state.notifications;persist();$('[data-action="toggle-notifications"]').setAttribute('aria-checked',String(state.notifications));toast(`Demo notifications ${state.notifications?'enabled':'muted'}.`);break;
    case 'form-back':if(formStep>1){captureDraft();formStep--;render();}else navigate('trips');break;
    case 'generate':navigate('itinerary');toast(`Itinerary generated with ${state.selected.length} selected stops.`);break;
    case 'recalculate':render();toast('Schedule recalculated using your departure time and selected stops.');break;
    case 'save-offline':offlinePlan();break;
    case 'close-modal':closeModal();break;
    case 'emergency':emergencyModal();break;
    case 'sos':confirmAlert();break;
    case 'alert-members':confirmAlert('your trip members');break;
    case 'alert-contacts':confirmAlert('your two sample trusted contacts');break;
    case 'confirm-sos':openModal('SOS simulation complete',`<span class="sos-symbol" style="background:var(--tint);color:var(--teal)">✓</span><p>The confirmation flow is complete. <strong>No alert was sent, and no one was contacted.</strong></p><p>In a serious emergency, use your phone to contact official emergency services immediately.</p><button class="btn wide" data-action="close-modal">Back to safety tools</button>`);break;
    case 'call-police':case 'call-ambulance':openModal(action==='call-police'?'Police call preview':'Ambulance call preview',`<p>This is a simulated call action. No call has been placed.</p><div class="location-preview">In an emergency, use your phone’s dialer to contact official ${action==='call-police'?'police':'ambulance'} services.<small>This prototype does not connect to emergency dispatch.</small></div><button class="btn wide" data-action="close-modal">Understood</button>`);break;
    case 'hospital':case 'police-station':openModal(action==='hospital'?'Nearby hospital preview':'Nearby police preview',`<p>Illustrative results near the mock Dambulla location. No actual search or location access has occurred.</p><div class="location-preview"><strong>${action==='hospital'?'Sample district hospital':'Sample local police station'}</strong><small>Demo distance: ${action==='hospital'?'2.4':'1.8'} km · Availability and directions unverified</small></div><p>Use a trusted live map or contact local services to find current assistance.</p><button class="btn wide" data-action="close-modal">Close preview</button>`);break;
    case 'share-location':openModal('Share location preview',`<p>This card uses a sample location. Your real location has not been accessed.</p><div class="location-preview"><strong>Near Dambulla, Central Province</strong><small>Mock coordinates: 7.8742° N, 80.6511° E</small></div><p>No location has been shared with anyone.</p><button class="btn wide" data-action="copy-location">${icon('share')}Copy mock location text</button>`);break;
    case 'copy-location':copyText('TripPulse DEMO location only — Near Dambulla, Sri Lanka. 7.8742° N, 80.6511° E. Not a live or actual device location.');break;
    case 'invite':openModal('Good trips need good company.',`<p>Preview an invitation to <strong>${escapeHTML(state.trip.name)}</strong>. Collaboration is simulated; there is no join link or connected group.</p><div class="location-preview">Come along: ${escapeHTML(state.trip.start)} → ${escapeHTML(state.trip.destination)}<small>${dateText()} · ${state.trip.group} travelers · ${escapeHTML(state.trip.style)} pace</small></div><button class="btn wide" data-action="copy-invite">${icon('users')}Copy sample invitation</button>`);break;
    case 'copy-invite':copyText(`Come along on ${state.trip.name}! ${state.trip.start} → ${state.trip.destination}, ${dateText()}. TripPulse prototype invitation — no live group or join link.`);break;
    case 'emergency-offline':downloadFile('TripPulse-emergency-info.txt','TRIPPULSE — OFFLINE EMERGENCY REFERENCE\n\nPrototype only. No live services.\nIn a serious emergency, contact official emergency services immediately using your phone.\n\nBefore leaving: verify local emergency numbers, save actual trusted-contact phone numbers, download a real offline map, and discuss a meeting point with your travel group.\n\nIf you need help: provide your actual location, the nature of the emergency, and a callback number.\n\nSample contacts: Nimal Kumar (family), Sara Perera (friend). These are fictional contacts with no phone numbers.\nMock location: near Dambulla — NOT your actual location.');toast('Offline emergency reference downloaded.');break;
    case 'emergency-profile':navigate('profile');break;
    case 'explore-from-modal':closeModal();navigate('explore');break;
    case 'logout':openModal('Leave the demo?',`<p>This prototype has no authentication session. Leaving returns you to the welcome screen; your local trip and preferences stay on this device.</p><div class="button-row"><button class="btn secondary" data-action="close-modal">Stay here</button><button class="btn" data-action="confirm-logout">Return to welcome</button></div>`);break;
    case 'confirm-logout':closeModal();navigate('welcome');toast('You’ve left the demo workspace. Your local plan is saved.');break;
  }
}
async function copyText(text) {try {if(!navigator.clipboard)throw new Error('Clipboard unavailable');await navigator.clipboard.writeText(text);toast('Sample text copied. Nothing was sent.');}catch{openModal('Copy your sample text',`<p>Clipboard access is unavailable. Select and copy this text manually.</p><textarea readonly rows="6" aria-label="Sample text to copy">${escapeHTML(text)}</textarea>`);$('#modal textarea').select();}}
function captureDraft() {const form=$('#trip-form');if(!form)return;for(const [key,value] of new FormData(form))draft[key]=key==='group'?Number(value):value.trim();}
document.addEventListener('click',event=>{
  const nav=event.target.closest('[data-nav]');if(nav){navigate(nav.dataset.nav);return;}
  const action=event.target.closest('[data-action]');if(action){handleAction(action.dataset.action);return;}
  const place=event.target.closest('[data-toggle-place]');if(place){const id=Number(place.dataset.togglePlace);state.selected=state.selected.includes(id)?state.selected.filter(value=>value!==id):[...state.selected,id].sort((a,b)=>a-b);persist();const oldScroll=window.scrollY;render();window.scrollTo({top:oldScroll,behavior:'instant'});$(`[data-toggle-place="${id}"]`)?.focus({preventScroll:true});return;}
  const interest=event.target.closest('[data-interest]');if(interest){const value=interest.dataset.interest;draft.interests=draft.interests.includes(value)?draft.interests.filter(i=>i!==value):[...draft.interests,value];render();$(`[data-interest="${value}"]`).focus({preventScroll:true});return;}
  const style=event.target.closest('[data-style]');if(style){draft.style=style.dataset.style;render();$(`[data-style="${draft.style}"]`).focus({preventScroll:true});return;}
  const prompt=event.target.closest('[data-prompt]');if(prompt){sendMessage(prompt.dataset.prompt);return;}
  const layer=event.target.closest('[data-layer]');if(layer){const name=layer.dataset.layer;layers.has(name)?layers.delete(name):layers.add(name);render();$(`[data-layer="${name}"]`).focus({preventScroll:true});return;}
  const pin=event.target.closest('[data-map-stop]');if(pin){mapStop=Number(pin.dataset.mapStop);render();$(`[data-map-stop="${mapStop}"]`)?.focus({preventScroll:true});return;}
  const discovery=event.target.closest('[data-place]');if(discovery)showPlace(Number(discovery.dataset.place));
});
document.addEventListener('submit',event=>{
  if(event.target.id==='trip-form'){event.preventDefault();if(!event.target.reportValidity())return;captureDraft();if(!draft.name||!draft.start||!draft.destination){toast('Please enter a trip name, start, and destination.');return;}if(formStep===1&&draft.start.toLowerCase()===draft.destination.toLowerCase()){toast('Choose a destination different from your starting point.');return;}if(formStep<3){formStep++;render();$('#trip-form input, #trip-form button')?.focus({preventScroll:true});}else{state.trip={...draft,interests:[...draft.interests]};persist();navigate('overview');toast('Your trip workspace is ready. Let the good planning begin.');}}
  if(event.target.id==='chat-form'){event.preventDefault();sendMessage($('#chat-message').value);}
  if(event.target.id==='profile-form'){event.preventDefault();const values=Object.fromEntries(new FormData(event.target));if(!values.name.trim()||!values.city.trim()){toast('Please enter a name and home city.');return;}state.profile={...values,name:values.name.trim(),city:values.city.trim()};persist();render();updateIdentity();toast('Profile saved on this device.');}
});
function updateIdentity() {$('.user-profile strong').textContent=state.profile.name;const initials=state.profile.name.split(' ').filter(Boolean).map(n=>n[0]).slice(0,2).join('');$$('.avatar-main').forEach(el=>el.textContent=initials);}
$('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const rect=$('#modal').getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)closeModal();}});
window.addEventListener('popstate',()=>{const screen=location.hash.slice(1);state.screen=screens[screen]?screen:'dashboard';render();});
state.screen=screens[location.hash.slice(1)]?location.hash.slice(1):'dashboard';render();updateIdentity();
